  assert.equal(lineTotal(line), 42500);
});

test('invoiceTotals sums line totals correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 42500 + 120000 = 162500
  // VAT: (42500 * 0.21) + (120000 * 0.21) = 8925 + 25200 = 34125
  // Total: 162500 + 34125 = 196625
  assert.equal(totals.subtotal, 162500);
  assert.equal(totals.vat, 34125);
  assert.equal(totals.total, 196625);
});

