      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports invalid quantity', () => {
  const cases = [
    { qty: 0, desc: 'zero' },
    { qty: -1, desc: 'negative' },
    { qty: 1.5, desc: 'fractional' },
    { qty: NaN, desc: 'NaN' },
  ];

  for (const { qty, desc } of cases) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-07',
        lines: [{ sku: 'DES-HOUR', qty }],
      }),
      { ok: false, error: 'QTY_INVALID' },
      `should reject ${desc}`
    );
