import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2026-10-07');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 2);

  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);

  assert.equal(invoice.lines[1].sku, 'LOGO-PACK');
  assert.equal(invoice.lines[1].name, 'Logo package');
  assert.equal(invoice.lines[1].qty, 1);
  assert.equal(invoice.lines[1].unitPrice, 120000);
  assert.equal(invoice.lines[1].vatRate, 21);
});

test('createInvoice reports an unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice reports an invalid date', () => {
  const invalidDates = ['2026-13-01', '2026-02-30', '26-10-07', '2026/10/07', '2026-10-7', ''];

  for (const date of invalidDates) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: date,
        lines: [{ sku: 'DES-HOUR', qty: 1 }],
      }),
      { ok: false, error: 'DATE_INVALID' },
      `should reject "${date}"`
    );
  }
});

test('createInvoice reports no lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports invalid quantity', () => {
  const cases = [
    { qty: 0, desc: 'zero' },
    { qty: -1, desc: 'negative' },
    { qty: 1.5, desc: 'fractional' },
    { qty: NaN, desc: 'NaN' },
  ];

  for (const { qty, desc } of cases) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-07',
        lines: [{ sku: 'DES-HOUR', qty }],
      }),
      { ok: false, error: 'QTY_INVALID' },
      `should reject ${desc}`
    );
  }
});

test('createInvoice reports an unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NOPE', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice returns a copy of the lines', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  result.value.lines[0].qty = 99;
  assert.equal(lines[0].qty, 1);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('invoiceTotals sums line totals correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 42500 + 120000 = 162500
  // VAT: (42500 * 0.21) + (120000 * 0.21) = 8925 + 25200 = 34125
  // Total: 162500 + 34125 = 196625
  assert.equal(totals.subtotal, 162500);
  assert.equal(totals.vat, 34125);
  assert.equal(totals.total, 196625);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 25500
  // VAT: 25500 * 0.21 = 5355
  // Total: 25500 + 5355 = 30855
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.vat, 5355);
  assert.equal(totals.total, 30855);
});

test('invoiceTotals with invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier, 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // Subtotal: 17000 + 120000 = 137000
  // VAT: (17000 * 0.21) + (120000 * 0.21) = 3570 + 25200 = 28770
  // Total: 137000 + 28770 = 165770
  assert.equal(totals.subtotal, 137000);
  assert.equal(totals.vat, 28770);
  assert.equal(totals.total, 165770);
});

test('addLine adds a new line to an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(result.value.lines[1].qty, 1);
  assert.equal(result.value.lines[1].unitPrice, 120000);
});

test('addLine increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine validates qty', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(
    addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: -1 }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('addLine validates SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(
    addLine(invoiceResult.value, { sku: 'NOPE', qty: 1 }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('addLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(
    addLine(invoice, { sku: 'LOGO-PACK', qty: 1 }),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('addLine does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const original = invoiceResult.value;
  const originalLineCount = original.lines.length;
  addLine(original, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(original.lines.length, originalLineCount);
});

test('removeLine removes a line from an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  const result = removeLine(invoiceResult.value, 'DES-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine reports line not found', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(
    removeLine(invoiceResult.value, 'NOPE'),
    { ok: false, error: 'LINE_NOT_FOUND' }
  );
});

test('removeLine reports error when removing last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(
    removeLine(invoiceResult.value, 'DES-HOUR'),
    { ok: false, error: 'NO_LINES' }
  );
});

test('removeLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };

  assert.deepEqual(
    removeLine(invoice, 'DES-HOUR'),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('removeLine does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  const original = invoiceResult.value;
  const originalLineCount = original.lines.length;
  removeLine(original, 'DES-HOUR');
  assert.equal(original.lines.length, originalLineCount);
});

test('issueInvoice changes status to issued and assigns number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = issueInvoice(invoiceResult.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.number, 'INV-2026-0001');
});

test('issueInvoice refuses to issue non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(
    issueInvoice(invoice, []),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('issueInvoice does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const original = invoiceResult.value;
  issueInvoice(original, []);
  assert.equal(original.status, 'draft');
  assert.equal(original.number, undefined);
});

test('issueInvoice with existing numbers from same year', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = issueInvoice(invoiceResult.value, ['INV-2026-0001', 'INV-2026-0005']);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0006');
});

test('issueInvoice preserves invoice properties', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const result = issueInvoice(invoiceResult.value, []);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'LOGO-PACK');
});

test('createInvoice accepts discountPercent on a line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice applies tier discount when discountPercent not provided', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (0%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice accepts decimal discount values', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 12.5);
});

test('createInvoice rejects negative discount', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -5 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects discount over 100', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects non-numeric discount', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('invoiceTotals calculates discount on a single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 5 * 8500 = 42500
  // Discount: 42500 * 10 / 100 = 4250
  // Amount after discount: 42500 - 4250 = 38250
  // VAT: 38250 * 21 / 100 = 8032.5 ≈ 8033 (rounded)
  // Total: 38250 + 8033 = 46283
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 8033);
  assert.equal(totals.total, 46283);
});

test('invoiceTotals calculates discount on multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 42500, discount = 4250, after discount = 38250, VAT = 8032.5 ≈ 8033
  // Line 2: 120000, discount = 6000, after discount = 114000, VAT = 23940
  // Subtotal: 162500
  // Total discount: 10250
  // Total VAT: 31973
  // Total: 162500 - 10250 + 31973 = 184223
  assert.equal(totals.subtotal, 162500);
  assert.equal(totals.discount, 10250);
  assert.equal(totals.vat, 31973);
  assert.equal(totals.total, 184223);
});

test('invoiceTotals with no discount returns zero discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 42500
  // Discount: 0
  // VAT: 42500 * 0.21 = 8925
  // Total: 42500 + 8925 = 51425
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 8925);
  assert.equal(totals.total, 51425);
});

test('invoiceTotals with 100% discount returns zero VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 100 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 42500
  // Discount: 42500 (100%)
  // Amount after discount: 0
  // VAT: 0 * 0.21 = 0
  // Total: 42500 - 42500 + 0 = 0
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('addLine with discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
