import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2026-10-07');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 2);

  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);

  assert.equal(invoice.lines[1].sku, 'LOGO-PACK');
  assert.equal(invoice.lines[1].name, 'Logo package');
  assert.equal(invoice.lines[1].qty, 1);
  assert.equal(invoice.lines[1].unitPrice, 120000);
  assert.equal(invoice.lines[1].vatRate, 21);
});

test('createInvoice reports an unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice reports an invalid date', () => {
  const invalidDates = ['2026-13-01', '2026-02-30', '26-10-07', '2026/10/07', '2026-10-7', ''];

  for (const date of invalidDates) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: date,
        lines: [{ sku: 'DES-HOUR', qty: 1 }],
      }),
      { ok: false, error: 'DATE_INVALID' },
      `should reject "${date}"`
    );
  }
});

test('createInvoice reports no lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports invalid quantity', () => {
  const cases = [
    { qty: 0, desc: 'zero' },
    { qty: -1, desc: 'negative' },
    { qty: 1.5, desc: 'fractional' },
    { qty: NaN, desc: 'NaN' },
  ];

  for (const { qty, desc } of cases) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-07',
        lines: [{ sku: 'DES-HOUR', qty }],
      }),
      { ok: false, error: 'QTY_INVALID' },
      `should reject ${desc}`
    );
  }
});

test('createInvoice reports an unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NOPE', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice returns a copy of the lines', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  result.value.lines[0].qty = 99;
  assert.equal(lines[0].qty, 1);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('invoiceTotals sums line totals correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 42500 + 120000 = 162500
  // VAT: (42500 * 0.21) + (120000 * 0.21) = 8925 + 25200 = 34125
  // Total: 162500 + 34125 = 196625
  assert.equal(totals.subtotal, 162500);
  assert.equal(totals.vat, 34125);
  assert.equal(totals.total, 196625);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
