  // BRAND-BOOK: 245000 cents = €2,450.00 each, VAT 9%, 3 × €7,350.00 = €7,350.00
  // WORKSHOP-DAY: 60000 cents = €600.00 each, VAT 0%, 2 × €1,200.00 = €1,200.00
  // Subtotal: €8,550.00
  // VAT on BRAND-BOOK: 735000 * 0.09 = 66150 cents = €661.50
  // VAT on WORKSHOP-DAY: 120000 * 0 = 0
  // Total VAT: €661.50
  // Total: €9,211.50
  assert.match(text, /€2,450\.00/);
  assert.match(text, /€7,350\.00/);
  assert.match(text, /€600\.00/);
  assert.match(text, /€1,200\.00/);
  assert.match(text, /VAT: €661\.50\n/);
  assert.match(text, /Total: €9,211\.50$/);
});

